package server

import (
	"google.golang.org/protobuf/reflect/protoreflect"

	"github.com/triodelab/model-plane/services/sandbox-manager/internal/workspace"
)

// snapshotDeletedPaths reads SnapshotRequest.deleted_paths (tag 5, F-f05-16)
// through protobuf reflection, so this package compiles against a generated
// gen/go that predates the field (the proto is regenerated by F-f05-99). Until
// that regeneration the descriptor has no such field and this returns nil, the
// same as a caller that sent none. After it, replace the call in SnapshotSandbox
// with req.GetDeletedPaths() and drop this file.
func snapshotDeletedPaths(req *SnapshotRequest) []workspace.DeletedPath {
	if req == nil {
		return nil
	}
	return deletedPathsFromMessage(req.ProtoReflect())
}

// deletedPathsFromMessage reads a repeated message field named deleted_paths,
// each element carrying string fields path and base_hash. Any other shape reads
// as no deletions rather than failing the snapshot.
func deletedPathsFromMessage(msg protoreflect.Message) []workspace.DeletedPath {
	fields := msg.Descriptor().Fields()
	field := fields.ByName("deleted_paths")
	if field == nil || !field.IsList() || field.Message() == nil {
		return nil
	}
	list := msg.Get(field).List()
	if list.Len() == 0 {
		return nil
	}
	out := make([]workspace.DeletedPath, 0, list.Len())
	for i := 0; i < list.Len(); i++ {
		item := list.Get(i).Message()
		itemFields := item.Descriptor().Fields()
		pathField, hashField := itemFields.ByName("path"), itemFields.ByName("base_hash")
		if pathField == nil || hashField == nil {
			return nil
		}
		out = append(out, workspace.DeletedPath{
			Path:     item.Get(pathField).String(),
			BaseHash: item.Get(hashField).String(),
		})
	}
	return out
}
